// Reads content/blog/*.md and writes src/lib/blog-data.generated.ts.
//
//   npm run blog:build           regenerate after adding or editing a post
//   npm run blog:build -- --check  exit 1 if the generated file is out of date (used by a test)
//
// Needs Node 22.6+ (it imports the TypeScript parser directly). The generated file is committed,
// so Vercel's build does not run this script.
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const { parsePost, sortPosts } = await import(pathToFileURL(join(root, 'src/lib/blog-content.ts')).href)

export function generate() {
  const dir = join(root, 'content/blog')
  const posts = readdirSync(dir)
    .filter((f) => f.endsWith('.md'))
    .map((f) => parsePost(f.replace(/\.md$/, ''), readFileSync(join(dir, f), 'utf8')))
  const sorted = sortPosts(posts)
  const slugs = new Set()
  for (const p of sorted) {
    if (slugs.has(p.slug)) throw new Error(`duplicate slug ${p.slug}`)
    slugs.add(p.slug)
  }
  return (
    '// GENERATED by scripts/build-blog-data.mjs from content/blog/*.md. Do not edit by hand.\n' +
    "import type { BlogPostData } from './blog-content'\n\n" +
    `export const BLOG_DATA: BlogPostData[] = ${JSON.stringify(sorted, null, 2)}\n`
  )
}

if (process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url) {
  const out = generate()
  const target = join(root, 'src/lib/blog-data.generated.ts')
  if (process.argv.includes('--check')) {
    const current = existsSync(target) ? readFileSync(target, 'utf8') : ''
    if (current !== out) {
      console.error('src/lib/blog-data.generated.ts is out of date. Run: npm run blog:build')
      process.exit(1)
    }
    console.log('blog data is up to date')
  } else {
    writeFileSync(target, out)
    console.log(`wrote ${target}`)
  }
}
